export type UnitCase="known_absolute"|"known_percent"|"zero_units"|"unknown_units"|"unknown_behavior"|"stale_period"|"one_time"|"reviewed";
export function unitScenario(name:UnitCase):{body:OperatingPlanBody;evaluation:OperatingEvaluation}{
 const base=encodedUnits.known_absolute as {body:Record<string,unknown>;evaluation:Record<string,unknown>},other=encodedUnits[name] as typeof base;
 return structuredClone({body:{...base.body,...other.body},evaluation:{...base.evaluation,...other.evaluation}}) as unknown as {body:OperatingPlanBody;evaluation:OperatingEvaluation};
}
/** State/geometry fixture uses a fixed result. Unit figures are copied from actual engine cases, never calculated in the browser. */
export function operatingEditReply(body:OperatingPlanBody){
 const raw=body as unknown as {unit_label?:string;historical_units_annual?:number|null;historical_units_period_start?:string;historical_units_period_end?:string;expenses?:Array<{volume_behavior?:string;cadence?:string}>;adjustments?:Array<{kind?:string;unit_change_mode?:string;status?:string}>};
 if(!raw.unit_label&&raw.historical_units_annual==null)return{evaluation:structuredClone(staffOperatingEvaluation),guidance:structuredClone(staffOperatingEvidence.guidance),evidence:structuredClone(staffOperatingEvidence)};
 const key:UnitCase=raw.historical_units_annual==null?"unknown_units":raw.historical_units_annual===0?"zero_units":raw.historical_units_period_start!==body.period_start||raw.historical_units_period_end!==body.period_end?"stale_period":raw.expenses?.some(row=>row.volume_behavior==="unknown")?"unknown_behavior":raw.expenses?.some(row=>row.cadence==="one_time")?"one_time":raw.adjustments?.some(row=>row.status==="approved")?"reviewed":raw.adjustments?.some(row=>row.unit_change_mode==="percent")?"known_percent":"known_absolute";
 const selected=unitScenario(key);const evidence=structuredClone(staffOperatingEvidence);
 evidence.files=body.expenses?.[0]?.source_file_ids?.map(file_id=>({...evidence.files[0],file_id,file_name:"Example annual operating statement.pdf"}))??evidence.files;
 evidence.guidance.business.name=body.business_name||"Example business";
 evidence.guidance.reporting={...evidence.guidance.reporting,period_start:body.period_start||evidence.guidance.reporting.period_start,period_end:body.period_end||evidence.guidance.reporting.period_end,currency:body.currency||evidence.guidance.reporting.currency};
 return{evaluation:selected.evaluation,guidance:evidence.guidance,evidence};
}
